SET @musa_v7_canonical_contract = '{"slug":"metodo-musa-7-dias","experienceVersion":"musa-pde-entry-v7-espelho-antes-de-sair","layoutKey":"espelho-antes-de-sair","funnelVersion":"musa-membership-funnel-v1","name":"Método MUSA - Presença Elegante em 7 Dias","promise":"Organizar em sete dias escolhas práticas de presença elegante prioritariamente com o que a cliente já possui, sem promessa de transformação garantida.","audience":"Mulheres urbanas que querem elevar presença, cuidado percebido e segurança visual com microações acessíveis.","priceLabel":"R$67","commercialCheckout":{"provider":"PEPPER","checkoutUrl":"https://go.pepper.com.br/owm6x","offerReference":"owm6x","priceBrl":67,"currency":"BRL","billingModel":"ONE_TIME"},"theme":{"primary":"#7a2444","accent":"#d6a75c","background":"#fff8f3","imageUrl":"/assets/musa-cover.png"},"diagnostic":{"title":"Primeiro ajuste MUSA","intro":"Responda 4 escolhas rápidas. O MUSA combina suas preferências por regras locais e sugere um ajuste pequeno para você testar com o que já possui.","questions":["Que mensagem sua imagem comunica sem intenção?","Em qual cena sua primeira impressão importa mais agora?","Qual sinal de presença você quer reforçar nesta semana?"]},"missions":[{"id":"dia-1-ruido-visual","day":1,"title":"O espelho não vê roupa, vê mensagem","principle":"A vestimenta participa da percepção de pessoa: antes de explicar quem você é, sua imagem já envia sinais.","action":"Vista uma combinação real e escreva a mensagem que ela parece transmitir hoje. Depois escolha um ajuste pequeno para aproximar essa mensagem da mulher que você quer comunicar.","evidence":"Frase preenchida: hoje minha imagem parece dizer...","visualCue":"Observe roupa, cabelo, pele e detalhe final como um conjunto de sinais, não como peças soltas.","interaction":{"guidanceType":"MUSA_V7_DAY_1_VISUAL_MESSAGE","kicker":"Consultora MUSA","title":"Organize a mensagem que sua imagem parece transmitir hoje.","helperText":"Escolha uma situação, o sinal per